# Each task: id, kind ("trap" = covered by the primer, "control" = not), prompt, tests (Lisp forms; all must be true)
TASKS = [
 dict(id="join-strings", kind="trap",
  prompt="Define (join-strings separator strings): return one string with the strings joined by separator. An empty list gives \"\".",
  tests=['(equal (join-strings ", " (list "a" "b" "c")) "a, b, c")', '(equal (join-strings "-" (list "x")) "x")', '(equal (join-strings "-" nil) "")']),
 dict(id="split-on-char", kind="trap",
  prompt="Define (split-on-char char string): return the list of substrings between occurrences of char, keeping empty fields. \"a,b,,c\" split on #\\, gives (\"a\" \"b\" \"\" \"c\"); the empty string gives (\"\").",
  tests=['(equal (split-on-char #\\, "a,b,,c") (list "a" "b" "" "c"))', '(equal (split-on-char #\\, "") (list ""))', '(equal (split-on-char #\; "abc") (list "abc"))', '(equal (split-on-char #\\, ",a,") (list "" "a" ""))']),
 dict(id="unique-strings", kind="trap",
  prompt="Define (unique-strings list): remove duplicate strings, keeping the FIRST occurrence of each, preserving order. Comparison is case-sensitive.",
  tests=['(equal (unique-strings (list "b" "a" "b" "c" "a")) (list "b" "a" "c"))', '(equal (unique-strings (list "A" "a")) (list "A" "a"))', '(null (unique-strings nil))']),
 dict(id="command-kind", kind="trap",
  prompt="Define (command-kind name): name is a string. \"start\" -> :start, \"stop\" -> :stop, \"restart\" -> :restart, anything else -> :unknown. Case-sensitive.",
  tests=['(eq (command-kind (copy-seq "start")) :start)', '(eq (command-kind (copy-seq "stop")) :stop)', '(eq (command-kind (concatenate (quote string) "re" "start")) :restart)', '(eq (command-kind "Start") :unknown)', '(eq (command-kind "") :unknown)']),
 dict(id="sorted-copy", kind="trap",
  prompt="Define (sorted-copy numbers): return a new list of the numbers sorted ascending. The argument list must not be modified.",
  tests=['(let* ((l (list 3 1 2)) (r (sorted-copy l))) (and (equal r (list 1 2 3)) (equal l (list 3 1 2))))', '(null (sorted-copy nil))', '(equal (sorted-copy (list 5 5 1)) (list 1 5 5))']),
 dict(id="hash-keys-sorted", kind="trap",
  prompt="Define (hash-keys-sorted table): table is a hash table with string keys; return the keys as a list sorted alphabetically with string<.",
  tests=['(let ((h (make-hash-table :test (quote equal)))) (setf (gethash "b" h) 1 (gethash "a" h) 2 (gethash "c" h) 3) (equal (hash-keys-sorted h) (list "a" "b" "c")))', '(null (hash-keys-sorted (make-hash-table :test (quote equal))))']),
 dict(id="safe-divide", kind="trap",
  prompt="Define (safe-divide a b) returning two values. If b is not zero: the exact quotient (a / b, which may be a ratio) and :ok. If b is zero: nil and :division-by-zero. No error may escape.",
  tests=['(multiple-value-bind (q s) (safe-divide 7 2) (and (= q 7/2) (eq s :ok)))', '(multiple-value-bind (q s) (safe-divide 1 0) (and (null q) (eq s :division-by-zero)))', '(multiple-value-bind (q s) (safe-divide 0 5) (and (eql q 0) (eq s :ok)))']),
 dict(id="lookup", kind="trap",
  prompt="Define (lookup key table default): table is an EQUAL hash table. Return two values: the stored value and T if key is present (even when the stored value is NIL); otherwise default and NIL.",
  tests=['(let ((h (make-hash-table :test (quote equal)))) (setf (gethash "k" h) nil) (multiple-value-bind (v f) (lookup "k" h :none) (and (null v) (eq f t))))', '(let ((h (make-hash-table :test (quote equal)))) (multiple-value-bind (v f) (lookup "zz" h :none) (and (eq v :none) (null f))))', '(let ((h (make-hash-table :test (quote equal)))) (setf (gethash (copy-seq "a") h) 5) (multiple-value-bind (v f) (lookup (copy-seq "a") h 0) (and (eql v 5) f)))']),
 dict(id="flatten-tree", kind="trap",
  prompt="Define (flatten-tree tree): flatten arbitrarily nested lists into one list of the non-nil atoms, in order. Empty lists disappear.",
  tests=['(equal (flatten-tree (quote ((1 (2 3)) nil 4 ((5))))) (list 1 2 3 4 5))', '(null (flatten-tree nil))', '(equal (flatten-tree (quote (a (b (c))))) (quote (a b c)))']),
 dict(id="make-counter", kind="trap",
  prompt="Define (make-counter): return a function of no arguments that, each time it is called, returns the next integer starting from 1. Separate counters are independent.",
  tests=['(let ((c (make-counter))) (funcall c) (funcall c) (= (funcall c) 3))', '(let ((a (make-counter)) (b (make-counter))) (funcall a) (funcall a) (= (funcall b) 1))', '(functionp (make-counter))']),
 dict(id="apply-n", kind="trap",
  prompt="Define (apply-n fn n x): apply the function fn to x, n times in a row, and return the result. n = 0 returns x.",
  tests=['(= (apply-n (function 1+) 5 0) 5)', '(equal (apply-n (lambda (l) (cons 0 l)) 3 nil) (list 0 0 0))', '(eq (apply-n (function 1+) 0 :x) :x)']),
 dict(id="alist-set", kind="trap",
  prompt="Define (alist-set alist key value): alist has string keys. Return a NEW alist in which key maps to value: an existing entry is replaced in place (order kept), otherwise the entry is added at the end. Other entries unchanged. The argument must not be modified. Key comparison is case-sensitive.",
  tests=['(let* ((a (list (cons "x" 1) (cons "y" 2))) (r (alist-set a "x" 9))) (and (equal r (list (cons "x" 9) (cons "y" 2))) (equal a (list (cons "x" 1) (cons "y" 2)))))', '(equal (alist-set nil "k" 1) (list (cons "k" 1)))', '(equal (alist-set (list (cons "a" 1)) (copy-seq "b") 2) (list (cons "a" 1) (cons "b" 2)))', '(equal (alist-set (list (cons "a" 1)) (copy-seq "a") 5) (list (cons "a" 5)))']),
 dict(id="parse-pairs", kind="trap",
  prompt="Define (parse-pairs string): parse \"a=1;b=22\" into an alist ((\"a\" . 1) (\"b\" . 22)): pairs separated by semicolons, name and integer value separated by =. The empty string gives nil.",
  tests=['(equal (parse-pairs "a=1;b=22") (list (cons "a" 1) (cons "b" 22)))', '(null (parse-pairs ""))', '(equal (parse-pairs "k=-5") (list (cons "k" -5)))']),
 dict(id="read-lines", kind="trap",
  prompt="Define (read-lines path): path is a string naming a text file. Return the list of its lines without newline characters. An empty file gives nil. Blank lines are kept.",
  tests=['(progn (with-open-file (s "/tmp/evalgrade-a.txt" :direction :output :if-exists :supersede) (format s "one~%two~%~%three~%")) (equal (read-lines "/tmp/evalgrade-a.txt") (list "one" "two" "" "three")))', '(progn (with-open-file (s "/tmp/evalgrade-b.txt" :direction :output :if-exists :supersede) nil) (null (read-lines "/tmp/evalgrade-b.txt")))']),
 dict(id="point-distance", kind="trap",
  prompt="Define a structure type POINT with slots X and Y (using defstruct with default options), and (point-distance p q) returning the Euclidean distance between two points.",
  tests=['(= (point-distance (make-point :x 0 :y 0) (make-point :x 3 :y 4)) 5)', '(let ((p (make-point :x 1 :y 2))) (and (= (point-x p) 1) (= (point-y p) 2) (point-p p)))', '(< (abs (- (point-distance (make-point :x 1 :y 1) (make-point :x 2 :y 2)) (sqrt 2.0))) 1e-4)']),
 dict(id="account-class", kind="trap",
  prompt="Define a CLOS class ACCOUNT with a slot balance (initarg :balance, initform 0, accessor account-balance), and a generic function (deposit account amount) that adds amount to the balance and returns the new balance. It must signal an ERROR (any error condition) when amount is not a positive number, leaving the balance unchanged.",
  tests=['(let ((a (make-instance (quote account) :balance 10))) (and (= (deposit a 5) 15) (= (account-balance a) 15)))', '(= (account-balance (make-instance (quote account))) 0)', '(let ((a (make-instance (quote account) :balance 10))) (and (handler-case (progn (deposit a -1) nil) (error () t)) (= (account-balance a) 10)))']),
 dict(id="parse-failure", kind="trap",
  prompt="Define a condition type PARSE-FAILURE (a subtype of ERROR) with a slot text (initarg :text, reader parse-failure-text), and (parse-digits string) which returns the integer for a non-empty string made only of the digits 0-9, and otherwise signals PARSE-FAILURE with text set to the string.",
  tests=['(= (parse-digits "123") 123)', '(equal (handler-case (parse-digits "12x") (parse-failure (c) (parse-failure-text c))) "12x")', '(typep (make-condition (quote parse-failure) :text "q") (quote error))', '(equal (handler-case (parse-digits "") (parse-failure (c) (parse-failure-text c))) "")']),
 dict(id="swap-values", kind="trap",
  prompt="Define a macro (swap-values a b) that swaps the values of two variables. It must work even when a variable is named TMP.",
  tests=['(let ((x 1) (y 2)) (swap-values x y) (equal (list x y) (list 2 1)))', '(let ((tmp 1) (y 2)) (swap-values tmp y) (equal (list tmp y) (list 2 1)))', '(let ((x 1) (tmp 2)) (swap-values x tmp) (equal (list x tmp) (list 2 1)))']),
 dict(id="while-macro", kind="trap",
  prompt="Define a macro (while test &body body) that repeats body as long as test is true. It returns nil.",
  tests=['(let ((i 0) (acc nil)) (while (< i 3) (push i acc) (incf i)) (equal (nreverse acc) (list 0 1 2)))', '(null (let ((n 0)) (while (< n 2) (incf n))))', '(let ((i 5)) (while (< i 3) (setf i 100)) (= i 5))']),
 dict(id="safe-parse-int", kind="trap",
  prompt="Define (safe-parse-int string): return the integer written in string (optional sign; leading and trailing whitespace allowed), or nil if the string is not entirely an integer. Must never signal an error.",
  tests=['(eql (safe-parse-int "42") 42)', '(eql (safe-parse-int " 42 ") 42)', '(eql (safe-parse-int "-7") -7)', '(null (safe-parse-int "12abc"))', '(null (safe-parse-int ""))', '(null (safe-parse-int "abc"))']),
 dict(id="average", kind="trap",
  prompt="Define (average numbers): the arithmetic mean of a list of numbers as a floating-point number, or nil for the empty list.",
  tests=['(= (average (list 1 2)) 1.5)', '(null (average nil))', '(floatp (average (list 2 4)))', '(= (average (list 1 2 4)) (/ 7 3.0))']),
 dict(id="last-n", kind="trap",
  prompt="Define (last-n list n): the last n elements of list as a list. If n is greater than the length, return the whole list; n = 0 gives nil.",
  tests=['(equal (last-n (list 1 2 3 4) 2) (list 3 4))', '(equal (last-n (list 1 2 3) 5) (list 1 2 3))', '(null (last-n (list 1 2 3) 0))', '(null (last-n nil 2))']),
 dict(id="group-by-length", kind="trap",
  prompt="Define (group-by-length strings): return an alist whose keys are string lengths and whose values are lists of the strings of that length. Groups appear in order of first occurrence of each length; within a group, strings keep their original order. Example: (\"a\" \"bb\" \"c\" \"dd\" \"eee\") gives ((1 \"a\" \"c\") (2 \"bb\" \"dd\") (3 \"eee\")).",
  tests=['(equal (group-by-length (list "a" "bb" "c" "dd" "eee")) (list (list 1 "a" "c") (list 2 "bb" "dd") (list 3 "eee")))', '(null (group-by-length nil))', '(equal (group-by-length (list "xx" "y")) (list (list 2 "xx") (list 1 "y")))']),
 dict(id="table-string", kind="trap",
  prompt="Define (table-string rows): rows is a list of lists of items. Return one string in which each row's items are printed with PRINC-style output (no quotes) separated by a TAB character, and each row is terminated by a newline character.",
  tests=['(equal (table-string (list (list 1 "a") (list 2 "b"))) (format nil "1~Aa~%2~Ab~%" (code-char 9) (code-char 9)))', '(equal (table-string nil) "")', '(equal (table-string (list (list "x"))) (format nil "x~%"))']),
 dict(id="fizzbuzz", kind="control",
  prompt="Define (fizzbuzz n): the list for 1..n where multiples of 3 become \"Fizz\", multiples of 5 become \"Buzz\", multiples of both become \"FizzBuzz\", and other numbers stay as numbers.",
  tests=['(equal (fizzbuzz 5) (list 1 2 "Fizz" 4 "Buzz"))', '(equal (car (last (fizzbuzz 15))) "FizzBuzz")', '(null (fizzbuzz 0))']),
 dict(id="collatz-length", kind="control",
  prompt="Define (collatz-length n): the number of steps for the Collatz sequence (n even -> n/2, n odd -> 3n+1) starting at positive integer n to reach 1. (collatz-length 1) is 0.",
  tests=['(= (collatz-length 1) 0)', '(= (collatz-length 6) 8)', '(= (collatz-length 27) 111)']),
 dict(id="palindrome-p", kind="control",
  prompt="Define (palindrome-p string): true when the string reads the same forwards and backwards, ignoring case and ignoring every character that is not a letter or digit; otherwise false.",
  tests=['(palindrome-p "A man, a plan, a canal: Panama")', '(not (palindrome-p "hello"))', '(palindrome-p "")', '(palindrome-p "No lemon, no melon")']),
 dict(id="matrix-transpose", kind="control",
  prompt="Define (matrix-transpose rows): rows is a non-empty rectangular list of lists; return its transpose as a list of lists.",
  tests=['(equal (matrix-transpose (list (list 1 2 3) (list 4 5 6))) (list (list 1 4) (list 2 5) (list 3 6)))', '(equal (matrix-transpose (list (list 1))) (list (list 1)))']),
]
